SELECT id FROM payment_outbox WHERE ((status IN ('NEW', 'RETRY') AND next_attempt_at<=CURRENT_TIMESTAMP(6)) OR (status='PROCESSING' AND next_attempt_at<CURRENT_TIMESTAMP(6)))
AND event_type <> 'OFFSITE_REFUND_SUCCEEDED'
ORDER BY id LIMIT #{batchSize}

SELECT command_id FROM payment_command_outbox WHERE command_type='CREATE_REFUND' AND ((status IN ('NEW',
  'RETRY') AND next_attempt_at<=CURRENT_TIMESTAMP(6)) OR (status='IN_FLIGHT' AND
  next_attempt_at<CURRENT_TIMESTAMP(6))) ORDER BY created_at LIMIT #{batchSize}
